{
  "code": "export default async function ({ page }) {
  const URL_LOGIN = 'https://app.cotadorsimplificado.com.br/login';

  await page.setViewport({ width: 1280, height: 800 });
  await page.goto(URL_LOGIN, { waitUntil: 'networkidle2', timeout: 60000 });
  await new Promise(r => setTimeout(r, 5000));

  // Pegar todos os inputs da pagina
  const inputs = await page.$$eval('input', els => els.map(el => ({
    id: el.id,
    name: el.name,
    type: el.type,
    placeholder: el.placeholder,
    className: el.className
  })));

  // Pegar todos os botoes
  const buttons = await page.$$eval('button', els => els.map(el => ({
    text: el.textContent.trim(),
    type: el.type,
    className: el.className
  })));

  // Tirar screenshot
  const screenshot = await page.screenshot({ encoding: 'base64' });

  return {
    url: page.url(),
    title: await page.title(),
    inputs: inputs,
    buttons: buttons,
    screenshot: screenshot.substring(0, 100) + '...'
  };
}"
}
